insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('9663859b-ba5e-48c9-a864-a63ed9ae4ab5', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$inleiding: waarom gaan goudvissen in een vissenkom dood$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context1.png$$,
   $$Goudvissen in een kom nemen weinig ruimte in, ze zijn goedkoop en decoratief. Mede door de prijs lijkt het soms wel een wegwerpartikel. Toch kunnen goudvissen bij een goede verzorging wel dertig jaar oud worden. Waardoor gaat het mis?$$, 'inline'),
  ('12679e35-85b8-4ed3-a86f-0427818d38b5', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$deaminering van aminozuren vormt ammoniak, uitgescheiden via de kieuwen$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context2.png$$,
   $$Een belangrijke oorzaak voor sterfte van vissen in een vissenkom of een aquarium heeft te maken met de stikstofkringloop. Visvoer bevat onder andere eiwitten. Bij de deaminering van aminozuren in de lever van de vis wordt ammoniak (NH₃) gevormd, dat in de vorm van ammoniumionen (NH₄⁺) via het bloed in de kieuwen terechtkomt en daar wordt uitgescheiden.$$, 'inline'),
  ('ebfd6f7e-b0c4-4019-90f2-8003b8b631b8', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$enkelvoudige bloedsomloop van een vis met vier bloedvaten (afbeelding 1)$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context3.png$$,
   $$In afbeelding 1 is de enkelvoudige bloedsomloop van een vis vereenvoudigd weergegeven.
afbeelding 1: schema van de enkelvoudige bloedsomloop van een vis, met pijlen die de stroomrichting van het bloed aangeven.
Vier bloedvaten van de vis zijn:
1 leverader
2 leverslagader
3 kieuwader
4 poortader$$, 'inline'),
  ('3f08f0ce-b96e-4aa0-834a-7c7b983f49c6', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$omzetting van ammoniak via Nitrosomonas en Nitrobacter tot nitraat (afbeelding 2)$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context4.png$$,
   $$Ammoniak en ammonium kunnen op verschillende manieren uit de vissenkom verdwijnen: doordat planten ze opnemen, door bacteriële activiteit en uiteraard als het water ververst wordt. De omzetting door de bacteriën van de geslachten Nitrosomonas en Nitrobacter is in afbeelding 2 weergegeven.
afbeelding 2: schema van de omzetting van ammoniak/ammonium door Nitrosomonas-bacteriën tot nitriet, en van nitriet door Nitrobacter-bacteriën tot nitraat.$$, 'inline'),
  ('c7a123f6-33bd-4373-b378-3ca94dfcf956', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$Nitrosomonas en Nitrobacter zijn chemo-autotroof$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context5.png$$,
   $$Nitrosomonas- en Nitrobacter-bacteriën zijn chemo-autotroof.$$, 'inline'),
  ('cf4808ee-6ed5-4049-a757-1b12d7534588', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$trage bacteriegroei laat nitriet gevaarlijk hoog oplopen, met effect op hemoglobine$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context6.png$$,
   $$In een nieuw ingerichte vissenkom komt de bacteriegroei maar langzaam op gang. Het duurt enige tijd voor zich een behoorlijke populatie Nitrosomonas heeft gevestigd, en Nitrobacter groeit nog trager. Nitriet is minder giftig dan ammoniak. Door het nog ontbreken van activiteit van Nitrobacter kan de concentratie van nitriet echter gevaarlijk hoog oplopen. Als vissen te veel nitriet via de kieuwen opnemen, worden rode bloedcellen afgebroken. Ook gaat dan hemoglobine over in methemoglobine, waardoor de zuurstofverzadigingscurve van de vis naar links verschuift.$$, 'inline'),
  ('28f4dcf8-a9a0-4676-8a82-876a74ea8f02', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$richtlijnen van Linda Walstad voor een low-tech beplante vissenkom$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context7.png$$,
   $$De vissenkom zou uitgebreid kunnen worden met filters en een circulatiesysteem om de waterkwaliteit op peil te houden. Linda Walstad beschrijft in haar boek Ecology of the planted aquarium een eenvoudige manier om dit te bereiken. Haar richtlijnen zijn als volgt: Bedek de bodem van een flinke kom met een laag tuinaarde waarin je verschillende soorten ondergedoken waterplanten plant. Dek de potgrond af met een laag kiezelsteentjes. Vul de kom met water en voeg daar je goudvissen aan toe. Zorg voor voldoende licht. Behalve het regelmatig voeren van de vissen heeft deze kom minimaal onderhoud nodig.$$, 'inline'),
  ('fdd43a2f-bf22-4988-ab64-d586019b64e0', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$de Walstad-methode houdt het gehalte giftige stoffen laag$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context8.png$$,
   $$Door toepassen van de Walstad-methode komt in de vissenkom een stikstofkringloop op gang waardoor het gehalte giftige stoffen in het water op een aanvaardbaar laag niveau kan worden gehouden.$$, 'inline'),
  ('27153105-291c-47ea-a96f-c1c76ce080bd', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', $$de vissenkom is geen gesloten ecosysteem$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-context9.png$$,
   $$De hierboven beschreven low-tech-vissenkom van Walstad is een ecosysteempje op zich. Het is echter geen gesloten ecosysteem doordat de kringlopen niet gesloten zijn en er aanvullende handelingen nodig zijn om het in stand te houden.$$, 'inline'),
  ('bcfc14e9-6e12-4b15-ad45-257047c0c460', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$citaat van hoogleraar Grootegoed over X-chromosomale inactivatie bij vrouwen$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context1.png$$,
   $$“Elke vrouw is een mozaïek”, zegt Anton Grootegoed, hoogleraar aan het Erasmus MC te Rotterdam. “Ze heeft groepjes cellen waarin het X-chromosoom dat van haar vader komt is uitgeschakeld, en groepjes waarin dat van haar moeder is uitgeschakeld.” Zijn afdeling ontdekte de moleculaire schakelaar die in vrouwelijke embryonale cellen één van beide X-chromosomen uitzet.$$, 'inline'),
  ('53c5b5e3-6f79-4ffe-986b-9ed109c39fd3', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$mechanisme van X-inactivatie en de vachtkleurgenetica van de lapjeskat (afbeelding 1, tabel 1)$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context2.png$$,
   $$Lichaamscellen van mannelijke en vrouwelijke zoogdieren bezitten een ongelijk aantal X-chromosomen. De genexpressie van X-chromosomale genen is echter ongeveer gelijk doordat bij vrouwen al tijdens de embryonale ontwikkeling in de cellen willekeurig één van beide X-chromosomen wordt geïnactiveerd. Hierdoor vindt geen transcriptie plaats van genen gelegen op dit X-chromosoom, ook niet bij de dochtercellen die hieruit ontstaan.
Bij een lapjeskat (altijd een vrouwtje, zie afbeelding 1) is in de vachtkleur het effect van de X-chromosomale inactivatie duidelijk zichtbaar. Er zijn drie genen die bij katten deze vachtkleur bepalen. De combinaties van allelen en het resulterende fenotype met betrekking tot deze drie genen zijn gegeven in tabel 1.
afbeelding 1: foto van een lapjeskat met zwarte, rode en witte vachtdelen.
tabel 1: het gen voor een donkere kleur (autosomaal) geeft bij BB, Bb of Bbl een zwarte vacht, bij bb of bbl een bruine vacht en bij blbl een lichtbruine vacht. Het gen voor rode kleuring (X-chromosomaal) geeft bij XRXR of XRY alle zwarte en bruine vachtdelen rood uitgevoerd, bij XRXr worden sommige zwarte en/of bruine vachtdelen rood, en bij XrXr of XrY veranderen zwarte en/of bruine vachtdelen niet. Het gen voor witte vlekken (autosomaal) geeft bij SS veel witte vlekken, bij Ss een aantal witte vlekken en bij ss nauwelijks of geen witte vlekken.$$, 'inline'),
  ('6c6fc1ba-688a-473e-bf36-ca4f1eb148e1', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$een lapjeskat met zwarte, rode en witte vlekken paart met een volledig bruine kater$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context3.png$$,
   $$Een lapjeskat met zwarte, rode en een aantal witte vlekken heeft gepaard met een volledig bruine kater.$$, 'inline'),
  ('ba4f4299-f2ff-4eec-97ca-78c27c42f728', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$twee lapjeskittens met verschillende vlekverdeling$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context4.png$$,
   $$In het nestje van de moederpoes zijn twee lapjeskittens geboren. Beide hebben zwarte, rode en een aantal witte vlekken, maar de verdeling van de vlekken over de vacht verschilt tussen deze twee kittens.
Naar aanleiding van dit verschil worden twee beweringen gedaan:
1 Hieruit blijkt dat het geen eeneiige tweeling kan zijn.
2 Hieruit blijkt dat deze kittens niet dezelfde vader hebben.$$, 'inline'),
  ('9cd40a51-64b9-41cb-a6d0-972df1be55a5', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$de ziekte van Fabry ontstaat door een mutatie in het gen voor α-galactosidase A$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context5.png$$,
   $$Bij de mens hebben vrouwen ook maar één werkzaam X-chromosoom. Dat kan een probleem worden als in een deel van haar lichaamscellen het X-chromosoom met een defect gen actief is, zoals bij de ziekte van Fabry. Deze ziekte is het gevolg van een mutatie in het gen dat codeert voor het enzym α-galactosidase A. Dit enzym is actief in lysosomen waarin afvalstoffen afgebroken worden. Bij een gebrek aan dit enzym hoopt een vetachtige stof GL-3 zich op in de lysosomen. Een fabry-patiënt kan hierdoor hart- en vaatproblemen krijgen, met een verhoogd risico op een hartinfarct en beschadiging van de nieren.$$, 'inline'),
  ('d45b6894-58ab-4bca-892b-0cab18fc09b4', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$afwijkend ECG bij Fabry-patiënten door verminderd functioneren van hartspiercellen (afbeelding 2)$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context6.png$$,
   $$De hartspiercellen functioneren door de ophoping van het GL-3 minder goed. Fabry-patiënten vertonen een afwijkend beeld op een electrocardiogram (ECG, zie afbeelding 2).
afbeelding 2: elektrocardiogram (ECG) van een fabry-patiënt met een afwijkend beeld.$$, 'inline'),
  ('bb4e5466-1643-4dc2-9d37-77a72127d166', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$aantasting van niereenheden bij Fabry en de mogelijke afwijkingen in de urine$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context7.png$$,
   $$Doordat ook verschillende celtypen in de niereenheden van een Fabry-patiënt worden aangetast, gaat de werking van de nieren achteruit.
Gevolgen van de ziekte van Fabry zijn:
1 aantasting cellen van de eerste gekronkelde buis
2 aantasting cellen van de glomerulus
3 aantasting cellen van de lis van Henle
4 vernauwde aanvoerende slagadertjes
Afwijkingen aan de urine als gevolg hiervan zijn:
P eiwitten in de urine
Q glucose in de urine
R minder creatinine-uitscheiding
S minder geconcentreerde urine$$, 'inline'),
  ('71142c55-8d6e-4eaa-9517-f67482d34481', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$onderzoek van het Erasmus MC naar de regeling van X-chromosoominactivatie (RNF12, Xist)$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context8.png$$,
   $$Uit onderzoek van het Erasmus MC blijkt hoe ingewikkeld de inactivatie van een X-chromosoom geregeld wordt:
1 Op het X-chromosoom ligt een inactivatie-centrum: een gebied waarin zich het RNF12-gen en het Xist-gen bevinden.
2 Vroeg in de embryonale ontwikkeling wordt in de cellen van het vrouwelijke embryo het RNF12-eiwit gevormd.
3 Wanneer de concentratie RNF12 boven een bepaalde drempel komt, wordt de transcriptie van Xist gestimuleerd.
4 Het Xist-RNA bedekt vervolgens het ‘eigen’ X-chromosoom dat hierdoor geïnactiveerd wordt.
5 Ook remt het Xist-RNA de productie van RNF12, zodat het tweede X-chromosoom niet wordt uitgeschakeld. In 12% van de cellen gebeurt dit echter te laat en sterft de cel nadat beide X-chromosomen geïnactiveerd zijn.$$, 'inline'),
  ('c9a199f4-4185-4bf6-9539-c74363b66932', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$DNA-strengen van een X-chromosoom met Xist-RNA in wording, uiteindes genummerd 1 t/m 6 (afbeelding 3)$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context9.png$$,
   $$In afbeelding 3 zijn de twee complementaire DNA-strengen van een X-chromosoom, met het Xist-RNA in wording, schematisch weergegeven.
afbeelding 3: schema van de twee DNA-strengen van een X-chromosoom met RNA-polymerase en het ontstane Xist-RNA; de uiteindes van de DNA- en RNA-strengen zijn met de nummers 1 tot en met 6 aangegeven.
De uiteindes van de DNA- en RNA-strengen zijn met de nummers 1 tot en met 6 aangegeven.$$, 'inline'),
  ('2eb95df1-aaeb-44ab-ac99-2f0239307951', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$transcriptie van RNF12 start op dag 8 van de embryonale ontwikkeling$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context10.png$$,
   $$In menselijke embryo’s start de transcriptie van RNF12 meestal op dag 8.$$, 'inline'),
  ('b970914b-6bf8-4d28-8caa-83aaee6e66a8', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$de invloed van X-chromosomale inactivatie op het fenotype is epigenetisch$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context11.png$$,
   $$De beïnvloeding van het fenotype door X-chromosomale inactivatie is epigenetisch.$$, 'inline'),
  ('0b519e51-aa84-4fc7-adfb-d3d841d6ea74', '308ed702-0eac-4677-bd7e-2e055d6d9257', $$ziekteverschijnselen van Fabry verschillen tussen mannen en vrouwen$$,
   $$biologie-vwo-2017-ii-x-chromosomale-inactivatie-context12.png$$,
   $$De ziekteverschijnselen bij mannelijke fabry-patiënten zijn ernstiger dan bij vrouwelijke patiënten, bij wie de ernst van de symptomen sterk varieert.$$, 'inline'),
  ('fc840fb9-6f1e-459f-bc5d-1cd38a1bb8c3', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$inleiding: verschillen tussen ogen van ongewervelden en gewervelden$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context1.png$$,
   $$Er zijn grote verschillen in de bouw en werking van ogen van ongewervelde en gewervelde dieren. Onderzoek naar overeenkomsten en verschillen tussen lichtreceptoren (lichtzintuigcellen) werpt een licht op de evolutionaire ontwikkeling ervan.$$, 'inline'),
  ('70e1b675-08fa-4f90-8dcd-de1ef72a3fc7', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$rhabdomere en ciliaire receptoren als twee oertypen lichtreceptoren (afbeelding 1)$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context2.png$$,
   $$Lichtreceptoren vangen licht (fotonen) op met behulp van pigmenten in geplooide membranen. Deze prikkels worden in het zenuwstelsel omgezet in impulsen. Er zijn twee oertypen lichtreceptoren: rhabdomere en ciliaire receptoren (zie afbeelding 1). De rhabdomere receptoren lijken kenmerkend voor ongewervelden, de ciliaire voor gewervelden.
afbeelding 1: schema van het oertype rhabdomere receptor en het oertype ciliaire receptor, beide met membraanuitstulpingen waarin pigment zit.$$, 'inline'),
  ('dfada54a-dee0-41dd-961e-6bd50c039c38', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$beide typen lichtreceptoren hebben membraanuitstulpingen$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context3.png$$,
   $$Beide typen lichtreceptoren bezitten membraanuitstulpingen.$$, 'inline'),
  ('b15503e3-cb02-4f07-a212-4104d1ced013', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$regeneratie van cis-retinal verschilt tussen ciliaire en rhabdomere opsinen (afbeelding 2)$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context4.png$$,
   $$De lichtreceptoren bevatten opsinen: eiwitten die, gebonden aan het pigment retinal, licht kunnen absorberen. Retinal komt voor in twee vormen (isomeren). Wanneer retinal in de cis-vorm een foton absorbeert, wordt het omgezet in trans-retinal. Bij ciliaire opsinen zijn enzymatische omzettingen in speciale hulpcellen nodig om dit trans-retinal weer terug te vormen naar de cis-retinal (zie afbeelding 2). De regeneratie bij rhabdomere opsinen is eenvoudiger: bij blootstelling aan een volgend foton verandert het trans-retinal weer terug in cis-retinal.
Afbeelding 2: schema van de omzetting van cis-retinal in trans-retinal door fotonen; bij ciliair opsine wordt trans-retinal via enzymatische omzetting door hulpcellen weer teruggevormd tot cis-retinal, bij rhabdomeer opsine gebeurt de terugvorming direct door blootstelling aan een volgend foton.$$, 'inline'),
  ('a29b21be-bd64-465f-9dae-bbbed2f7acb8', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$twee beweringen over gevoeligheid en opsinegebruik van ciliaire en rhabdomere receptoren$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context5.png$$,
   $$Over het functioneren van de twee typen lichtreceptoren worden op basis van bovenstaande informatie twee beweringen gedaan:
1 In fel licht raken ciliaire receptoren eerder ongevoelig voor prikkels dan rhabdomere receptoren.
2 Voor een gelijke prikkelwaarneming zijn in rhabdomere receptoren (vanwege de snelle regeneratie van cis-retinal) meer opsines nodig dan in ciliaire receptoren.$$, 'inline'),
  ('9c416caf-0d95-4c18-82e6-6e27d80aeae7', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$lichtreceptoren lijken op zenuwcellen: rustpotentiaal en Na⁺-kanalen$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context6.png$$,
   $$Lichtreceptoren hebben grote overeenkomsten met zenuwcellen. Zo zijn ze negatief geladen ten opzichte van het omringende milieu en is de intracellulaire Na⁺-concentratie lager dan in het omringende milieu. Lichtprikkels leiden tot een verandering van de membraanpotentiaal in lichtreceptoren. In rhabdomere receptoren openen daardoor de Na⁺-kanalen. In ciliaire receptoren, zoals de staafjes in ons netvlies, leidt dit juist tot het sluiten van Na⁺-kanalen.$$, 'inline'),
  ('c22a9335-9045-411f-bc53-81d95efc7e85', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$het handhaven van de rustpotentiaal kost energie$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context7.png$$,
   $$Het handhaven van een rustpotentiaal kost energie en gebeurt in ciliaire en rhabdomere receptoren op gelijke wijze.$$, 'inline'),
  ('0a3f9e99-4d0d-4695-81ec-57d81483b33a', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$opsinevarianten (c-opsine, G0-opsine, r-opsine, melanopsine) bij mens en andere dieren$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context8.png$$,
   $$Er bestaan veel varianten van het eiwit opsine. In ciliaire receptoren worden c-opsinen of G0-opsinen gevonden, in rhabdomere receptoren r-opsinen of melanopsinen. Bij de mens vind je ciliaire opsinen in de zintuigcellen (staafjes en kegeltjes) in het netvlies van het oog. Melanopsinen zitten in zenuwcellen in het netvlies van ons oog en hebben een functie bij de regeling van het circadiane (dag-nacht)ritme. In afbeelding 3 is een ordening op basis van overeenkomsten in aminozuurvolgorde van de opsinen weergegeven.$$, 'inline'),
  ('0c9695df-7332-4726-b70f-ddbfc092a0d8', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$cladogram van opsinevarianten bij verschillende diergroepen (afbeelding 3)$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context9.png$$,
   $$afbeelding 3: cladogram van opsinevarianten bij verschillende diergroepen, ingedeeld in de takken CILIAIR (c-opsine bij onder andere kwal, gewervelden-kegeltjes, gewervelden-staafjes en borstelworm; G0-opsine bij sint-jakobsschelp en lancetvisje) en RHABDOMEER (r-opsine bij borstelworm, pijlinktvis, sint-jakobsschelp, degenkrab en insecten; melanopsine bij gewervelden-circadiane neuronen en lancetvisje).$$, 'inline'),
  ('d0a9ff5c-018f-4b72-8af0-c6ed90026b1a', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$twee beweringen over de gemeenschappelijke oorsprong van rhabdomere en ciliaire receptoren$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context10.png$$,
   $$De gevonden overeenkomsten en verschillen tussen de typen opsinen van verschillende (groepen van) dieren wijzen op een gemeenschappelijke oorsprong van rhabdomere en ciliaire lichtreceptoren. Twee beweringen hierover zijn:
1 De oertypen van rhabdomere en ciliaire receptoren waren er al voor het ontstaan van de eerste gewervelden.
2 De staafjes zijn in de evolutie van gewervelden eerder ontstaan dan de kegeltjes.$$, 'inline'),
  ('06cea6e3-c178-4ae3-bf87-0418a78aab79', '1c27dd70-7462-4a71-b2af-b3b553380e72', $$vijf deelprocessen die leiden tot analogie of homologie van lichtreceptoren$$,
   $$biologie-vwo-2017-ii-evolutie-van-lichtreceptoren-context11.png$$,
   $$Verschillen en overeenkomsten van lichtreceptoren kunnen duiden op een analoge of homologe evolutionaire ontwikkeling. Een aantal evolutionaire deelprocessen die leiden tot analogie of homologie van lichtreceptoren zijn in onderstaande zinnen gegeven:
1 Er is lichtgevoeligheid ontstaan in een celtype van een gemeenschappelijke voorouder.
2 Er is lichtgevoeligheid ontstaan in bepaalde celtypes in verschillende voorouders.
3 Door mutaties zijn varianten hiervan ontstaan.
4 Er zijn steeds meer overeenkomsten tussen de varianten ontstaan.
5 Er zijn steeds meer verschillen tussen de varianten ontstaan.$$, 'inline'),
  ('e7f07032-1ed3-40d4-90ee-306b3b332ba0', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$inleiding: de wereldwijde bananenproductie wordt bedreigd door de Panama-ziekte$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context1.png$$,
   $$Bananen zijn de belangrijkste voedselbron voor meer dan 400 miljoen mensen in de tropen. De wereldwijde bananenproductie wordt bedreigd door schimmels die de Panama-ziekte veroorzaken. Wetenschappers en studenten van Wageningen UR onderzoeken hoe je deze ziekte bij bananenplanten kunt voorkomen en bestrijden.$$, 'inline'),
  ('53822c90-fe13-4b23-9f1c-e470c84467ba', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$de Cavendish-cultivar wordt aangetast door een nieuwe variant van Fusarium oxysporum$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context2.png$$,
   $$De meest gegeten banaan komt van de cultivar ‘Cavendish’ van de bananenplant Musa acuminata. Deze cultivar was tot voor kort ongevoelig voor de Panama-ziekte, veroorzaakt door de schimmel Fusarium oxysporum. Inmiddels is er een nieuwe variant van deze schimmel verschenen, F. oxysporum TR4, die ook de Cavendish-cultivars aantast. De schimmel infecteert de bananenplanten vanuit sporen in de bodem, waarna de schimmeldraden vanuit de wortels de transportvaten in groeien.$$, 'inline'),
  ('719b303a-99b0-4648-a654-a58c32dba040', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$de triploïde, zaadloze Cavendish is ontstaan uit twee varianten van de diploïde wilde bananenplant (afbeelding 1)$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context3.png$$,
   $$De wilde bananenplant is diploïd en vormt zaden. De triploïde Cavendish is ontstaan uit twee varianten van M. acuminata. De Cavendish-cultivar bezit twee sets chromosomen van de ene ouder en één set van de andere ouder, in totaal 33 chromosomen. De bananen van deze cultivar hebben géén zaden. In afbeelding 1 is naast een Cavendish zonder zaden, een doorgesneden ‘wilde’ banaan mét zaden te zien.
afbeelding 1: foto van een opengesneden zaadloze Cavendish-banaan naast een doorgesneden wilde banaan met zaden.$$, 'inline'),
  ('df682c3d-f347-4e6a-ae9a-10043abacbf8', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$Cavendish-telers vermeerderen planten via ondergrondse zijknoppen$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context4.png$$,
   $$Omdat bananenplanten na de bloei afsterven en er geen zaden beschikbaar zijn, moeten Cavendish-telers op een andere manier aan nieuwe planten komen. Dat doen ze door ondergrondse zijknoppen af te snijden en op te kweken tot nieuwe planten.$$, 'inline'),
  ('3b118c4c-1398-4a2c-9fd7-d12e1c1945a4', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$Kema brengt resistentiegenen uit de Pahang-bananenplant in bij de Cavendish via genetische modificatie$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context5.png$$,
   $$Doordat de Cavendish-planten geen zaden vormen, is klassieke veredeling uitgesloten als methode om ze minder gevoelig te maken voor F. oxysporum. De Wageningse onderzoeker Gert Kema gebruikt daarom genetische modificatie: hij probeert resistentie-genen tegen de schimmel uit een ander bananenras, M. acuminata ssp. malaccensis, (de Pahang-bananenplant) in te brengen bij de Cavendish.$$, 'inline'),
  ('bc6ac559-3c2c-4786-bfc0-790aa226ca22', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$genetische modificatie is goedkoper en sneller dan klassieke veredeling$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context6.png$$,
   $$Veredeling door genetische modificatie is, in vergelijking met klassieke veredeling door kunstmatige selectie, goedkoper en geeft een sneller resultaat.$$, 'inline'),
  ('302fd58e-fd78-44f9-ab23-1ffba8575054', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$bouw van de bananenplant: schijnstam, ondergrondse stengel en neerhangende bloeiwijze (afbeelding 2)$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context7.png$$,
   $$Bananenplanten zijn géén bomen, want ze hebben geen echte stam. De schijnstam bestaat uit strak om elkaar gevouwen bladstelen die groeien vanuit een ondergrondse stengel. Vanuit het centrum van de schijnstam groeit een enorme bloeiwijze die door zijn toenemende gewicht naar beneden gaat hangen (zie afbeelding 2). De zetmeelrijke vruchten buigen tijdens hun groei naar boven: dáárom zijn de bananen krom!
afbeelding 2: schema van een bananenplant met schijnstam, ondergrondse stengel, zijknop en de naar beneden hangende bloeiwijze.$$, 'inline'),
  ('54bda823-450c-4f2f-9c93-42466ae53ffe', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$F. oxysporum verstopt met fusarinezuur de houtvaten van de bananenplant$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context8.png$$,
   $$F. oxysporum produceert fusarinezuur, een toxine waarmee de schimmel de plant kan binnendringen. De schimmeldraden verstoppen op den duur een deel van de houtvaten van de bananenplant.$$, 'inline'),
  ('f9baaa62-6871-4493-b870-ff2e70659fbe', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$rijpe bananen bevatten veel zetmeel$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context9.png$$,
   $$Rijpe bananen bevatten veel zetmeel.$$, 'inline'),
  ('bf1778a1-a4b4-4182-82c9-b822f93d0598', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$de fusarinezuur-resistente bacterie Pseudomonas putida wordt gemodificeerd tot ''BananaGuard'' (afbeelding 3)$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context10.png$$,
   $$Een alternatieve aanpak van de Panama-ziekte richt zich op het onschadelijk maken van de schimmel F. oxysporum met behulp van een fusarinezuur-resistente schimmelremmende bacterie. Een groep Wageningse studenten modificeerde de fusarinezuur-resistente bodembacterie Pseudomonas putida (afbeelding 3) op zo’n manier dat deze alleen schimmelremmende stoffen gaat produceren als er fusarinezuur in de bodem komt. Ze gaven deze bacterie de naam ‘BananaGuard’.
afbeelding 3: elektronenmicroscopische foto van de bacterie Pseudomonas putida met flagellen.$$, 'inline'),
  ('a0c46e84-89fc-4670-8422-a3a20f7e586a', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$de kromming van bananen kan door zwaartekracht of door licht beïnvloed worden$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context11.png$$,
   $$Dat de bananen (de vruchten) naar boven krommen als de bloeiwijze naar beneden hangt, kan wijzen op beïnvloeding door de zwaartekracht of beïnvloeding door het licht.$$, 'inline'),
  ('c51ed0b0-469d-462b-8b99-12ff42c02cdb', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$BananaGuard vormt alleen bij contact met fusarinezuur het resistentie-eiwit, geregeld via promotor en regulatoreiwit$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context12.png$$,
   $$De gemodificeerde BananaGuard-bacterie vormt, alleen als zij in contact komt met fusarinezuur, een eiwit dat fusarinezuur de cel uitpompt. Het gen dat codeert voor dit eiwit is dus het fusarinezuur-resistentiegen. Dit gen heeft een promotor. De transcriptie van de promotor (en dus van het resistentiegen) is afhankelijk van onder andere een regulatoreiwit, gecodeerd door een regulatorgen. In afbeelding 4 zijn schematisch vier manieren getekend waarop deze promotor gereguleerd zou kunnen worden.$$, 'inline'),
  ('e3c71f5a-76d4-4bbf-9402-3e945c9da1b7', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$vier schema''s van mogelijke regulatie van de promotor door fusarinezuur (afbeelding 4)$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context13.png$$,
   $$afbeelding 4: vier schema''s (1 tot en met 4) van bacterie-DNA met een regulatorgen en een promotorgen, waarbij fusarinezuur de regulator stimuleert of remt, en de regulator op zijn beurt de promotor stimuleert of remt (legenda: pijl = stimulering, blokje = remming).$$, 'inline'),
  ('e9823b3c-a447-46e2-b445-a0f0ecdcfc74', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$het genconstruct met detectie-eenheid voor fusarinezuur en genen voor schimmelremmende stoffen$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context14.png$$,
   $$De studenten brachten in P. putida een genconstruct waarin een detectie-eenheid zit voor fusarinezuur, en een aantal genen die coderen voor stoffen die de groei van allerlei schimmels remmen. De BananaGuard-bacteriën gaan pas schimmelremmers produceren als ze fusarinezuur in de bodem detecteren.$$, 'inline'),
  ('b9dca8b1-c139-4c0c-b461-d5fcd287fb73', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$een toxine-antitoxine-construct op twee plasmiden moet verspreiding van het genconstruct voorkomen$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context15.png$$,
   $$De Wageningse studenten willen het risico uitsluiten dat het genconstruct door uitwisseling van plasmiden tussen bacteriën in andere bodembacteriën terechtkomt. Daartoe hebben ze een toxine-antitoxine-construct ontworpen dat op twee afzonderlijke plasmiden in elke BananaGuard-bacterie ingebouwd wordt. Een van deze plasmiden bevat ook het genconstruct dat bescherming biedt tegen F. oxysporum.$$, 'inline'),
  ('0d29c0c9-31f9-4b91-a530-820d10fe2277', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$de toxinegenen Zeta en Kid en hun antitoxinegenen op vier genplaatsen (afbeelding 5)$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context16.png$$,
   $$Gebruikt worden de genen voor de toxines Zeta (Z) en Kid (K) die dodelijk zijn voor bacteriën, plus een gen voor een antitoxine dat Zeta neutraliseert (anti-Z) en een gen voor een antitoxine tegen Kid (anti-K). De vier plaatsen waar deze genen worden ingebouwd zijn in afbeelding 5 met nummers aangegeven. De genen voor beide antitoxines staan ‘aan’, waardoor de expressie van de bijpassende toxines in de BananaGuard wordt onderdrukt.
afbeelding 5: schema van een BananaGuard-bacterie met celwand en flagel, met twee plasmiden die elk twee genplaatsen bevatten (plaats 1 en 2 op het ene plasmide, plaats 3 en 4 op het andere).$$, 'inline'),
  ('4799fa0a-49e8-4460-837e-fc7eb589a38c', '31abfef0-e8fc-46fa-99d0-b3dcbaf645b5', $$een slimme verdeling van de vier genen over twee plasmiden verkleint het verspreidingsrisico$$,
   $$biologie-vwo-2017-ii-bananen-bedreigd-context17.png$$,
   $$Door een slimme combinatie van de vier genen, verdeeld over twee plasmiden per bacterie, is gebruik van deze BananaGuard-bacterie op de plantage wel effectief tegen schimmels, maar wordt het risico op verspreiding van het genconstruct naar andere bodembacteriën verkleind.$$, 'inline'),
  ('e38790d6-a959-49ca-9b5d-08fc7e25878f', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$forumbericht van Nicky en algemene informatie over de ziekte van Pfeiffer en het EBV (afbeelding 1)$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context1.png$$,
   $$Op een internetforum plaatst Nicky het volgende bericht (afbeelding 1).
afbeelding 1: forumbericht van Nicky (Topic: Pfeiffer?, gelezen 179 keer, gepost op 3 juli 2016, 15:35): ''''Hallo allemaal, Een week geleden kreeg ik heel veel last van mijn keel en later kreeg ik koorts. Nu ga ik morgen naar de dokter toe om bloed te prikken, want ze weten bijna zeker dat ik Pfeiffer heb. Nou zal het me eigenlijk niks verbazen als ik het heb. Mijn vraag is aan jullie is: Hoe snel ben je weer van Pfeiffer af? En blijf je lang besmettelijk? Liefs!''''
De ziekte van Pfeiffer wordt veroorzaakt door het Epstein-Barr-virus (EBV). Meer dan 90 procent van de bevolking is zonder het te merken drager van dit virus dat door speekselcontact (bijvoorbeeld zoenen) wordt overgedragen. Van een eerste besmetting word je na ongeveer 4 tot 7 weken ziek en daarna blijf je levenslang drager. Bij jonge kinderen verloopt de ziekte vaak ongemerkt, maar bij jongvolwassenen, zoals Nicky (afbeelding 1), is het verloop heftiger. De eerste symptomen van de ziekte van Pfeiffer zijn vermoeidheid, keelpijn en koorts en na een week komen daar keelontsteking en gezwollen lymfklieren bij. De vermoeidheid kan maanden duren.$$, 'inline'),
  ('b6bb8384-0e3c-4f81-ac37-1c3135801a31', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$de huisarts controleert of de lymfklieren van Nicky gezwollen zijn$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context2.png$$,
   $$De huisarts zal bij het eerste onderzoek voelen of bij Nicky de lymfklieren in de hals, en eventueel ook die in de oksels en liezen, gezwollen zijn. Het volume van de lymfklieren kan voelbaar toenemen als gevolg van de activatie van de specifieke afweer.$$, 'inline'),
  ('e9267ced-fb64-4ca7-b864-f79328fff639', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$verloop van antistofconcentraties (EA, VCA, EBNA) na infectie en na reactivatie (afbeelding 2)$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context3.png$$,
   $$Het EBV bezit een aantal specifieke antigenen (EA, VCA en EBNA) waartegen antistoffen worden gemaakt die in het bloed aangetoond kunnen worden. Op internet vindt Nicky een diagram (afbeelding 2) dat het verloop toont van de concentratie van verschillende antistoffen in combinatie met de ernst van de symptomen na een eerste besmetting en na reactivatie, een periode waarin opnieuw virusdeeltjes worden geproduceerd. De drager merkt zelf doorgaans niets van deze reactivatie.
afbeelding 2: diagram met bovenin de ernst van de symptomen (een piek rond de start van de symptomen) en onderin de relatieve concentratie van de antistoffen EA-IgG/M, VCA-IgM, VCA-IgG en EBNA-IgG tegen de tijd (in maanden) na infectie; EA-IgG/M en VCA-IgM pieken kort na de start van de symptomen en dalen weer, VCA-IgG en EBNA-IgG blijven op de lange termijn aanwezig; bij reactivatie treedt opnieuw een piek van EA-IgG/M op en stijgt VCA-IgG tijdelijk, terwijl EBNA-IgG op een constant hoog niveau blijft.$$, 'inline'),
  ('0790c4df-7447-4b54-8b50-66d4b1ac35c6', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$Nicky laat de dag na haar forumbericht bloed afnemen voor onderzoek$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context4.png$$,
   $$De dag na haar forumbericht laat Nicky bloed afnemen voor onderzoek.$$, 'inline'),
  ('cd99b6cd-b00f-4d5e-9434-9a2b3c610b5c', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$infectiecyclus van EBV via epitheelcellen en B-cellen, met latente fase en reactivatie (afbeelding 3)$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context5.png$$,
   $$De sterke reactie van het immuunsysteem na een eerste besmetting is de oorzaak van de vermoeidheid bij de ziekte van Pfeiffer. Als je door bijvoorbeeld een zoen voor het eerst besmet wordt met EBV raken eerst de epitheelcellen van de mond- en keelholte geïnfecteerd (zie afbeelding 3).
afbeelding 3: schema van de infectiecyclus van EBV: het virus infecteert epitheelcellen, die virusdeeltjes produceren waarmee een B-cel wordt geïnfecteerd; de geïnfecteerde B-cel wordt een actieve B-cel en vervolgens (via een latente fase) een B-geheugencel; bij reactivatie ondergaat de B-geheugencel lysis, waarbij nieuwe virusdeeltjes vrijkomen.
Deze epitheelcellen gaan virusdeeltjes produceren die op hun beurt B-cellen infecteren in het lymfweefsel van de keelholte. Door expressie van de virusgenen delen deze B-cellen en differentiëren in geheugencellen. Een groot deel van deze cellen blijft latent geïnfecteerd, dat wil zeggen dat het virusgenoom wel aanwezig is, maar er worden geen virussen geproduceerd. Zo nu en dan gaat een van deze cellen de lytische fase in (reactivatie) en kunnen er weer virusdeeltjes vrijkomen. Die komen in het speeksel terecht en kunnen worden overgedragen aan een volgende gastheer.$$, 'inline'),
  ('ca462128-02f6-4dbd-b6b0-d7cded9a4ecd', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$MHC-II als co-receptor waarvan het EBV gebruikmaakt om B-cellen binnen te dringen$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context6.png$$,
   $$B-cellen hebben een receptor op het celoppervlak waarvan het EBV gebruikmaakt. Deze receptor, in combinatie met een MHC-II molecuul als co-receptor, maakt fusie met het celmembraan van de gastheercel mogelijk. MHC-II moleculen zijn niet bedoeld om virussen de cellen in te laten.$$, 'inline'),
  ('d9438d99-fdb2-4355-b43e-b83b8ab93b16', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$het virale eiwit BHRF1 maakt geïnfecteerde B-cellen ''onsterfelijk''$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context7.png$$,
   $$Geïnfecteerde B-cellen worden door het virus ‘onsterfelijk’ gemaakt doordat een viraal eiwit BHRF1 wordt gevormd dat analoog is aan het menselijk BCL-2-eiwit dat celdood (apoptose) remt.$$, 'inline'),
  ('44228efe-8173-4786-aa49-c3ab7c75bfe4', '885c9e1d-ea12-42cc-b28c-22a18ad29401', $$Nicky stelt op het forum twee vragen over hersteltijd en besmettelijkheid$$,
   $$biologie-vwo-2017-ii-de-ziekte-van-pfeiffer-context8.png$$,
   $$Op het internetforum stelt Nicky twee vragen (afbeelding 1 op pagina 18).$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('6016137a-a0cc-4388-aa89-eee4259ec720', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["enkelvoudige bloedsomloop", "deaminering", "ammoniakuitscheiding", "leverader", "kieuwen"]'::jsonb,
   $$Bepalen via welke bloedvaten een ammoniakmolecuul van de lever naar de kieuwen stroomt.$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-vraag1.png$$, $$Door welk of welke van deze bloedvaten passeert een ammoniakmolecuul op de kortste route van de plaats van vorming tot de plaats van uitscheiding? Zet de nummers 1 tot en met 4 onder elkaar op je antwoordblad en noteer bij elk nummer of het betreffende bloedvat wel of niet op die kortste route ligt.$$, array['9663859b-ba5e-48c9-a864-a63ed9ae4ab5','12679e35-85b8-4ed3-a86f-0427818d38b5','ebfd6f7e-b0c4-4019-90f2-8003b8b631b8']::uuid[]),
  ('9bb7166e-5f11-4c55-aab0-93bcaadaa2ae', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', 2,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["chemosynthese", "autotrofie", "anorganische energiebron", "chemo-autotroof"]'::jsonb,
   $$Uitleggen wat chemo-autotrofe bacteriën kenmerkt.$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-vraag2.png$$, $$Wat houdt het begrip chemo-autotroof in?$$, array['c7a123f6-33bd-4373-b378-3ca94dfcf956']::uuid[]),
  ('d766f45d-b2a6-4316-a596-0b37f425da9e', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', 3,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["nitrificatie", "stikstofbindende bacteriën", "aerobe dissimilatie", "anaerobe dissimilatie"]'::jsonb,
   $$Nitrobacter indelen bij de nitrificerende bacteriën en de aerobe omzetting van nitriet naar nitraat herkennen.$$,
   $$biologie-vwo-2017-ii-ecologie-in-een-vissenkom-vraag3.png$$, $$Behoort Nitrobacter tot de nitrificerende of tot de stikstofbindende bacteriën? En verloopt de omzetting van nitriet in nitraat sneller onder aerobe of anaerobe omstandigheden?
Nitrobacter behoort tot de: / De omzetting verloopt sneller onder:
A nitrificerende bacteriën / aerobe omstandigheden
B nitrificerende bacteriën / anaerobe omstandigheden
C stikstofbindende bacteriën / aerobe omstandigheden
D stikstofbindende bacteriën / anaerobe omstandigheden$$, array['3f08f0ce-b96e-4aa0-834a-7c7b983f49c6','c7a123f6-33bd-4373-b378-3ca94dfcf956']::uuid[]),
  ('a36e2b33-aefe-4f08-80bf-1bdb8b10bd2d', '4f062997-9ed2-4062-bee5-5079e1cbb5b4', 4,
